 90	    private FaqBid createAndSaveOrderBid(Product user, UserSize productSize, int bidPrice, Faq order) {
 91	        FaqBid orderBid = FaqBid.builder()
 92	                .user(user)
 93	                .productSize(productSize)
 94	                .bidPrice(bidPrice)
 95	                .status(BidStatus.PENDING)
 96	                .order(order)
 97	                .build();
 98	
 99	
100	        orderBid.assignOrder(order);
101	
102	        return orderBidRepository.save(orderBid);
103	    }
