172	    private StyleBid getSaleBidAndValidate(Long saleBidId) {
173	        StyleBid saleBid = saleBidQueryService.findById(saleBidId);
174	        if (saleBid == null) {
175	            throw new StyleBidNotFoundException("판매 입찰을 찾을 수 없습니다(ID: " + saleBidId + ")");
176	        }
177	
178	        Style sale = saleBid.getSale();
179	        if (sale == null) {
180	            throw new InvalidFaqBidDataException("판매 입찰과 연결된 판매 정보가 없습니다.");
181	        }
182	
183	        return saleBid;
184	    }
