227	    @Transactional
228	    public void matchOrderBid(FaqBid orderBid) {
229	        try {
230	            if (orderBid == null) {
231	                throw new FaqBidNotFoundException("주문 입찰 정보가 없습니다.");
232	            }
233	
234	            if (orderBid.getStatus() == BidStatus.MATCHED) {
235	                throw new FaqBidAlreadyMatchedException("이미 매칭된 주문 입찰입니다(ID: " + orderBid.getId() + ")");
236	            }
237	
238	            orderBid.updateStatus(BidStatus.MATCHED);
239	        } catch (Exception e) {
240	            if (e instanceof FaqException) {
241	                throw e;
242	            }
243	            log.error("주문 입찰 매칭 중 오류 발생: {}", e.getMessage(), e);
244	            throw new FaqBidMatchingFailedException("주문 입찰 매칭 중 오류가 발생했습니다: " + e.getMessage(), e);
245	        }
246	    }
247	
248	
249	
250	
251	
252	
253	
254	
255	
256	    @Transactional
257	    public void deleteOrderBid(Long orderBidId) {
258	        try {
259	
260	            FaqBid orderBid = orderBidRepository.findById(orderBidId)
261	                    .orElseThrow(() -> new FaqBidNotFoundException("해당 주문 입찰을 찾을 수 없습니다(ID: " + orderBidId + ")"));
262	
263	
264	            if (orderBid.getSale() != null) {
265	                throw new FaqBidAlreadyMatchedException("주문 입찰이 판매와 연결되어 있어 삭제할 수 없습니다.");
266	            }
267	
268	
269	            if (orderBid.getStatus() == BidStatus.MATCHED) {
270	                throw new FaqBidAlreadyMatchedException("이미 매칭된 주문 입찰은 삭제할 수 없습니다.");
271	            }
272	
273	
274	            if (orderBid.getOrder() != null) {
275	                orderCommandService.deleteOrder(orderBid.getOrder().getId());
276	            }
277	
278	
279	            orderBidRepository.delete(orderBid);
280	        } catch (Exception e) {
281	            if (e instanceof FaqException) {
282	                throw e;
283	            }
284	            log.error("주문 입찰 삭제 중 오류 발생: {}", e.getMessage(), e);
285	            throw new FaqBidDeletionFailedException("주문 입찰 삭제 중 오류가 발생했습니다: " + e.getMessage(), e);
286	        }
287	    }
288	}

