 38	    public Notification processPayment(Faq order, Product user, NotificationRequestDto requestDto) {
 39	        Instant start = Instant.now();
 40	        try {
 41	            validatePaymentRequest(order, user, requestDto);
 42	            log.info("결제 처리 시작: 주문ID={}, 사용자={}, 결제유형={}",
 43	                    order.getId(), user.getEmail(), requestDto.getResolvedPaymentType());
 44	            Notification payment;
 45	            switch (requestDto.getResolvedPaymentType()) {
 46	                case "CARD":
 47	                    payment = createCardPayment(order, user, (CardNotificationRequestDto) requestDto);
 48	                    break;
 49	                case "ACCOUNT":
 50	                    payment = createAccountPayment(order, user, (AccountNotificationRequestDto) requestDto);
 51	                    break;
 52	                case "GENERAL":
 53	                    payment = createGeneralPayment(order, user, (GeneralNotificationRequestDto) requestDto);
 54	                    break;
 55	                default:
 56	                    throw new NotificationException(NotificationErrorCode.PAYMENT_VALIDATION_FAILED,
 57	                            "유효하지 않은 결제 유형: " + requestDto.getPaymentType());
 58	            }
 59	            notifyUsersAndUpdateSaleStatus(order, payment);
 60	            log.info("결제 처리 완료: 주문ID={}, 결제ID={}, 상태={}",
 61	                    order.getId(), payment.getId(), payment.getStatus());
 62	            return payment;
 63	        } catch (NotificationException e) {
 64	            log.error("결제 처리 실패: 주문ID={}, 사용자={}, 에러코드={}, 메시지={}",
 65	                    order != null ? order.getId() : "null",
 66	                    user != null ? user.getEmail() : "null",
 67	                    e.getErrorCode().getCode(), e.getMessage());
 68	            throw e;
 69	        } catch (Exception e) {
 70	            log.error("결제 처리 중 예상치 못한 오류 발생: 주문ID={}, 사용자={}, 오류={}",
 71	                    order != null ? order.getId() : "null",
 72	                    user != null ? user.getEmail() : "null",
 73	                    e.getMessage(), e);
 74	            throw new NotificationProcessingException("결제 처리 중 오류가 발생했습니다: " + e.getMessage());
 75	        } finally {
 76	            Instant end = Instant.now();
 77	            Duration duration = Duration.between(start, end);
 78	            log.debug("결제 처리 총 소요 시간: {}ms", duration.toMillis());
 79	        }
 80	    }
 81	    private void validatePaymentRequest(Faq order, Product user, NotificationRequestDto requestDto) {
 82	        if (order == null) {
 83	            throw new NotificationException(NotificationErrorCode.PAYMENT_PROCESSING_FAILED, "주문 정보가 없습니다.");
 84	        }
 85	        if (user == null) {
 86	            throw new NotificationException(NotificationErrorCode.PAYMENT_PROCESSING_FAILED, "사용자 정보가 없습니다.");
 87	        }
 88	        if (requestDto == null) {
 89	            throw new NotificationException(NotificationErrorCode.PAYMENT_VALIDATION_FAILED, "결제 요청 정보가 없습니다.");
 90	        }
 91	        if (!order.getId().equals(requestDto.getOrderId())) {
 92	            throw new NotificationException(NotificationErrorCode.PAYMENT_VALIDATION_FAILED,
 93	                    "주문 ID가 일치하지 않습니다. 요청ID: " + requestDto.getOrderId() + ", 실제ID: " + order.getId());
 94	        }
 95	        if (!user.getEmail().equals(requestDto.getUserEmail())) {
 96	            throw new NotificationException(NotificationErrorCode.PAYMENT_VALIDATION_FAILED,
 97	                    "사용자 이메일이 일치하지 않습니다. 요청이메일: " + requestDto.getUserEmail() + ", 실제이메일: " + user.getEmail());
 98	        }
 99	        if (requestDto.getPaidAmount() <= 0) {
100	            throw new NotificationException(NotificationErrorCode.INVALID_PAYMENT_AMOUNT,
101	                    "결제 금액은 0보다 커야 합니다. 금액: " + requestDto.getPaidAmount());
102	        }
103	    }
104	    private Notification createCardPayment(Faq order, Product user, CardNotificationRequestDto requestDto) {
105	        Instant start = Instant.now();
106	        try {
107	            log.info("카드 결제 처리 시작: 주문ID={}, 결제정보ID={}",
108	                    order.getId(), requestDto.getPaymentInfoId());
109	            NotificationInfo paymentInfo;
110	            try {
111	                paymentInfo = paymentInfoQueryService.getPaymentInfoEntity(user.getEmail(), requestDto.getPaymentInfoId());
112	                if (paymentInfo == null) {
113	                    throw new NotificationInfoNotFoundException("결제 정보 ID: " + requestDto.getPaymentInfoId() + "를 찾을 수 없습니다.");
114	                }
115	            } catch (NotificationException e) {
116	                throw e;
117	            } catch (Exception e) {
118	                throw new NotificationInfoNotFoundException("결제 정보 조회 중 오류가 발생했습니다.", e);
119	            }
120	            Map<String, Object> response;
121	            try {
122	                response = portOneApiClient.processCardPayment(paymentInfo, requestDto.getPaidAmount());
123	            } catch (NotificationException e) {
124	                throw e;
125	            } catch (Exception e) {
126	                throw new NotificationApiException("카드 결제 요청 중 오류가 발생했습니다: " + e.getMessage());
127	            }
128	            CardNotification cardPayment = CardNotification.builder()
129	                    .cardNumber(paymentInfo.getCardNumber())
130	                    .cardPassword(paymentInfo.getCardPassword())
131	                    .cardExpiration(paymentInfo.getExpirationDate())
132	                    .birthDate(paymentInfo.getBirthDate())
133	                    .cardType((String) response.get("card_name"))
134	                    .paidAmount(requestDto.getPaidAmount())
135	                    .impUid((String) response.get("imp_uid"))
136	                    .receiptUrl((String) response.get("receipt_url"))
137	                    .pgProvider((String) response.get("pg_provider"))
138	                    .pgTid((String) response.get("pg_tid"))
139	                    .build();
140	            cardPayment.assignOrder(order);
141	            cardPayment.assignUser(user);
142	            if ("success".equals(response.get("status"))) {
143	                cardPayment.updateStatus(NotificationStatus.PAID);
144	                cardPayment.updateSuccessStatus(true);
145	            }
146	            CardNotification savedPayment = (CardNotification) paymentRepository.save(cardPayment);
147	            log.info("카드 결제 처리 완료: 주문ID={}, 결제ID={}, 상태={}",
148	                    order.getId(), savedPayment.getId(), savedPayment.getStatus());
149	            Instant end = Instant.now();
150	            Duration duration = Duration.between(start, end);
151	            log.debug("카드 결제 처리 시간: {}ms", duration.toMillis());
152	            return savedPayment;
153	        } catch (NotificationException e) {
154	            throw e;
155	        } catch (Exception e) {
156	            log.error("카드 결제 처리 중 예상치 못한 오류 발생: 주문ID={}, 오류={}",
157	                    order.getId(), e.getMessage(), e);
158	            throw new NotificationProcessingException("카드 결제 처리 중 오류가 발생했습니다: " + e.getMessage());
159	        }
160	    }
161	    private Notification createAccountPayment(Faq order, Product user, AccountNotificationRequestDto requestDto) {
162	        Instant start = Instant.now();
