263	    private void notifyUsersAndUpdateSaleStatus(Faq order, Notification payment) {
264	        try {
265	            log.info("결제 관련 알림 및 판매 상태 업데이트 시작: 주문ID={}", order.getId());
266	            FaqBid orderBid = order.getOrderBid();
267	            if (orderBid == null) {
268	                StyleBid saleBid = saleBidQueryService.findByOrderId(order.getId());
269	                if (saleBid == null) {
270	                    log.warn("주문에 연결된 판매 입찰 정보가 없습니다: 주문ID={}", order.getId());
271	                    return;
272	                }
273	                Style sale = saleBid.getSale();
274	                if (sale == null) {
275	                    log.warn("판매 입찰에 연결된 판매 정보가 없습니다: 판매입찰ID={}", saleBid.getId());
276	                    return;
277	                }
278	                sendNotifications(order, sale);
279	                sale.updateStatus(StyleStatus.SOLD);
280	                log.info("판매 상태 업데이트 완료: 판매ID={}, 상태=SOLD", sale.getId());
281	                return;
282	            }
283	            Style sale = orderBid.getSale();
284	            if (sale == null) {
285	                log.warn("주문 입찰에 연결된 판매 정보가 없습니다: 주문입찰ID={}", orderBid.getId());
286	                return;
287	            }
288	            sendNotifications(order, sale);
289	            sale.updateStatus(StyleStatus.SOLD);
290	            log.info("판매 상태 업데이트 완료: 판매ID={}, 상태=SOLD", sale.getId());
291	        } catch (Exception e) {
292	            log.error("결제 관련 알림 및 판매 상태 업데이트 중 오류 발생: 주문ID={}, 오류={}",
293	                    order.getId(), e.getMessage(), e);
294	        }
295	    }
296	    private void sendNotifications(Faq order, Style sale) {
297	        try {
298	            Product buyer = order.getUser();
299	            if (buyer != null) {
300	                notificationCommandService.createNotification(
301	                        buyer.getId(),
302	                        PaymentCategory.SHOPPING,
303	                        PaymentType.BID,
304	                        "결제가 완료되었습니다. 주문 ID: " + order.getId()
305	                );
306	                log.debug("구매자 알림 전송 완료: 구매자ID={}", buyer.getId());
307	            }
