341	    @Transactional
342	    public void updatePaymentStatus(Notification payment, NotificationStatus newStatus) {
343	        Instant start = Instant.now();
344	        try {
345	            if (payment == null) {
346	                throw new NotificationNotFoundException("결제 정보가 없습니다.");
347	            }
348	            if (!payment.getStatus().canTransitionTo(newStatus)) {
349	                throw new NotificationException(NotificationErrorCode.INVALID_PAYMENT_STATUS,
350	                        "현재 상태(" + payment.getStatus() + ")에서 " + newStatus + " 상태로 변경할 수 없습니다.");
351	            }
352	            log.info("결제 상태 변경: 결제ID={}, 현재상태={}, 새상태={}",
353	                    payment.getId(), payment.getStatus(), newStatus);
354	            payment.updateStatus(newStatus);
355	            paymentRepository.save(payment);
356	            log.info("결제 상태 변경 완료: 결제ID={}, 상태={}", payment.getId(), newStatus);
357	            Instant end = Instant.now();
358	            Duration duration = Duration.between(start, end);
359	            log.debug("결제 상태 변경 처리 시간: {}ms", duration.toMillis());
360	        } catch (NotificationException e) {
361	            log.error("결제 상태 변경 실패: 결제ID={}, 에러코드={}, 메시지={}",
362	                    payment != null ? payment.getId() : "null",
363	                    e.getErrorCode().getCode(), e.getMessage());
364	            throw e;
365	        } catch (Exception e) {
366	            log.error("결제 상태 변경 중 예상치 못한 오류 발생: 결제ID={}, 오류={}",
367	                    payment != null ? payment.getId() : "null", e.getMessage(), e);
368	            throw new NotificationException(NotificationErrorCode.PAYMENT_UPDATE_FAILED,
369	                    "결제 상태 변경 중 오류가 발생했습니다.", e);
370	        }
371	    }
372	    @Transactional
373	    public String refundPayment(Long paymentId) {
374	        Instant start = Instant.now();
375	        try {
376	            log.info("결제 환불 요청 시작: 결제ID={}", paymentId);
377	            Notification payment = paymentRepository.findById(paymentId)
378	                    .orElseThrow(() -> new NotificationNotFoundException("결제 ID: " + paymentId + "를 찾을 수 없습니다."));
379	            if (!payment.getStatus().canTransitionTo(NotificationStatus.REFUND_REQUESTED)) {
380	                throw new NotificationException(NotificationErrorCode.INVALID_PAYMENT_STATUS,
381	                        "현재 상태에서 환불 요청을 진행할 수 없습니다. 현재 상태: " + payment.getStatus());
382	            }
383	            if (payment.getImpUid() == null || payment.getImpUid().isBlank()) {
384	                throw new NotificationException(NotificationErrorCode.PAYMENT_CANCELLATION_FAILED,
385	                        "환불 가능한 결제 ID가 없습니다.");
386	            }
387	            boolean refundSuccess = portOneApiClient.cancelPayment(payment.getImpUid());
388	            if (refundSuccess) {
389	                payment.updateStatus(NotificationStatus.REFUNDED);
390	                paymentRepository.save(payment);
391	                log.info("결제 환불 요청 성공: 결제ID={}, 상태=REFUNDED", paymentId);
392	                sendRefundNotification(payment);
393	                Instant end = Instant.now();
394	                Duration duration = Duration.between(start, end);
395	                log.debug("결제 환불 처리 시간: {}ms", duration.toMillis());
396	                return "환불이 성공적으로 완료되었습니다.";
397	            } else {
398	                payment.updateStatus(NotificationStatus.REFUND_REQUESTED);
399	                paymentRepository.save(payment);
400	                log.warn("결제 환불 요청 실패: 결제ID={}, 상태=REFUND_REQUESTED", paymentId);

