27:@Transactional
28:@RequiredArgsConstructor
29:@Slf4j
30:public class PaymentCommandService {
31:
32:    private final PaymentRepository notificationRepository;
33:    private final ProductRepository userRepository;
34:    private final SimpMessagingTemplate messagingTemplate;
35:    private final RedisTemplate<String, String> redisTemplate;
36:
37:    private static final String REDIS_KEY_PREFIX = "WebSocket:Product:";
38:    private static final String WEBSOCKET_DESTINATION = "/queue/notifications";
39:    private static final int REDIS_TTL_MINUTES = 30;
40:
41:
42:
