44:    public PaymentDTO createNotification(Long userId, PaymentCategory category, PaymentType type, String message) {
45:        try {
46:            Product user = userRepository.findById(userId)
47:                    .orElseThrow(() -> new PaymentException(
48:                            PaymentErrorCode.NOTIFICATION_USER_NOT_FOUND,
49:                            "사용자 ID: " + userId + "를 찾을 수 없습니다."
50:                    ));
51:
52:            Payment notification = buildNotification(user, category, type, message);
53:            Payment savedNotification = notificationRepository.save(notification);
54:            log.info("알림 생성 완료: 사용자={}, 카테고리={}, 타입={}", user.getEmail(), category, type);
55:
56:
57:            sendRealTimeNotification(user.getEmail(), toDTO(savedNotification));
58:
59:            return toDTO(savedNotification);
60:        } catch (PaymentException e) {
61:            throw e;
62:        } catch (Exception e) {
63:            log.error("알림 생성 중 오류 발생: 사용자ID={}, 카테고리={}, 타입={}, 오류={}",
64:                    userId, category, type, e.getMessage(), e);
65:            throw new PaymentException(PaymentErrorCode.NOTIFICATION_CREATION_FAILED, e);
66:        }
67:    }
68:
69:
70:
71:
72:    public List<PaymentDTO> createNotificationForAll(PaymentRequestDTO requestDTO) {
73:        try {
74:            List<Product> allUsers = userRepository.findAll();
75:            if (allUsers.isEmpty()) {
76:                log.warn("알림 대상 사용자가 없습니다.");
77:                return List.of();
78:            }
79:
80:            log.info("전체 사용자 알림 생성 시작: 카테고리={}, 타입={}, 대상 사용자 수={}",
81:                    requestDTO.getCategory(), requestDTO.getType(), allUsers.size());
